/*
 * A061651  Numbers with all even digits in which each nonzero digit divides
 *          the number formed by the rest, i.e., the number obtained by just
 *          removing this digit. 0 is divisible by every number.
 * https://oeis.org/A061651
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn, base, easy
 * Formula:   a(n) is the nth integer (starting with a(1)=0) that consists
 *            only of even digits and satisfies that for each non‑zero digit d
 *            the number obtained by deleting this digit is divisible by d.
 *            The sequence is generated by enumerating numbers of increasing
 *            length
 * Range:     u8 n <= 21, u16 n <= 53, u32 n <= 53, u64 n <= 53, u128 n <= 53,
 *            big any n
 * Helpers:   pow10_local
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

/* Minimal includes */
#include <stdlib.h>
#include <stdbool.h>
#include "../utils/pow10_local.h"

/* Cached terms */
static seq_t *cache      = NULL; /* array of terms            */
static idx_t cache_len   = 0;    /* number of stored terms    */
static idx_t cache_cap   = 0;    /* current capacity          */
static idx_t next_len    = 1;    /* length of next numbers to generate */

/* Allocate or grow cache */
static void push_term(seq_t val)
{
    if (cache_len == cache_cap) {
        cache_cap = (cache_cap == 0) ? 8 : cache_cap << 1;
        cache = (seq_t *)realloc(cache, cache_cap * sizeof(seq_t));
    }
    cache[cache_len++] = val;
}

/* Test whether number 'n' of given decimal length 'len' satisfies the condition */
static bool is_good(seq_t n, idx_t len)
{
    for (idx_t pos = 0; pos < len; ++pos) {
        seq_t p10       = pow10_local(pos);     /* 10^pos          */
        seq_t p10_next  = p10 * 10;             /* 10^(pos+1)      */
        seq_t digit_seq = (n / p10) % 10;       /* digit at pos    */
        int    d        = (int)digit_seq;      /* narrow to int   */
        if (d == 0) continue;                  /* 0 always satisfies   */
        seq_t high = n / p10_next;              /* higher digits   */
        seq_t low  = n % p10_next;              /* lower digits    */
        seq_t removed = high * p10 + low;       /* number after deletion */
        if (removed % (seq_t)d != 0) return false;
    }
    return true;
}

/* Recursive generation of all even‐digit numbers of a fixed length */
static void gen_len_rec(idx_t pos, idx_t len, seq_t val)
{
    if (pos == len) {
        if (is_good(val, len))
            push_term(val);
        return;
    }
    int start = (pos == 0) ? 2 : 0;  /* first digit cannot be 0 */
    for (int d = start; d <= 8; d += 2) {
        seq_t new_val = val * 10 + (seq_t)d;
        gen_len_rec(pos + 1, len, new_val);
    }
}

/* Generate all numbers of the current length and extend the cache */
static void generate_len(idx_t len)
{
    gen_len_rec(0, len, (seq_t)0);
}

/* Public function required by the build */
seq_t a(idx_t n)
{
    if (n == 0) return (seq_t)0;        /* safety */

    /* Ensure at least a(1)=0 is in the cache */
    if (cache_len == 0)
        push_term((seq_t)0);            /* a(1) = 0 */

    /* Expand cache until it contains the nth term */
    while (cache_len < n) {
        generate_len(next_len);
        ++next_len;
    }
    return cache[n - 1];
}
